            dialogService.error(error, { fallbackMessage: 'Could not load agent conversations' })
        }
    }

    async select(path: string) {
        const request = this.loadRequest + 1
        this.loadRequest = request
        if (!path) {
            this.setSnapshot({ ...this.snapshot, selectedConversation: null })
            this.clearPromptDraft()
            return
        }

        try {
            const conversation = await defaultLoadConversation(path)
            if (request !== this.loadRequest) return
            this.validateSelection(conversation)

            this.setSnapshot({ ...this.snapshot, selectedConversation: conversation })
            this.clearPromptDraft()
        } catch (error) {
            if (request === this.loadRequest) {
                dialogService.error(error, { fallbackMessage: 'Could not load agent conversation' })
            }
        }
    }

    conversationOptions(liveConversation: AgentConversation | null): AgentConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null): ConversationPickerConversation[]
    conversationOptions(liveConversation: ConversationPickerConversation | null) {
        const selected = this.snapshot.selectedConversation
        const conversations = selected ? [...this.snapshot.conversations, selected] : this.snapshot.conversations

        return conversationOptions(conversations, this.actionId, this.context, liveConversation)
    }

    continuationPath(liveConversation: AgentConversation | null) {
        return liveConversation?.path ?? this.snapshot.selectedConversation?.path ?? null
    }

    /** Applies one backend-returned conversation without another persistence round trip. */
    updateConversation(conversation: AgentConversation) {
        this.validateSelection(conversation)
        const conversations = this.snapshot.conversations.some(({ path }) => path === conversation.path)
            ? this.snapshot.conversations.map((current) => (current.path === conversation.path ? conversation : current))
            : [...this.snapshot.conversations, conversation]
        const selectedConversation = this.snapshot.selectedConversation?.path === conversation.path
            ? conversation
            : this.snapshot.selectedConversation
        this.setSnapshot({ ...this.snapshot, conversations, selectedConversation })
    }

    private clearPromptDraft() {
        const run = actionRunRegistry.getActionRunStore(this.actionId, this.context)?.getSnapshot() ?? null
        actionPromptDraftService.clearDraft(this.actionId, this.context, run)
    }

    private validateSelection(conversation: AgentConversation) {
        if (!belongsToContext(conversation, this.context)) throw new Error('Selected agent conversation belongs to another context')
        if (conversation.actionId !== this.actionId) throw new Error('Selected agent conversation belongs to another action')
    }

    private setSnapshot(snapshot: ActionConversationSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { Stack, Typography } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { ActionConversationChatOwner } from '../../conversation/action_conversation_chat_owner'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionAgentInteraction } from './action_agent_interaction'
import { ActionRunDisabledMessage } from './action_run_disabled_message'
import type { ActionPopupRuntime } from './action_popup_types'

interface AgentActionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    baseContext: ActionContext
    popupEntryId?: string
    readOnlyMessage: string | null
    runtime: ActionPopupRuntime
}

/** Agent conversation, prompt, interaction, and scheduling content. */
export function AgentAction(props: AgentActionProps) {
    const { action, assignmentContext, baseContext, popupEntryId, readOnlyMessage, runtime } = props
    const { conversationStore, runValidationError, scheduleStore, settingsStore } = runtime

    if (readOnlyMessage) {
        return (
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                <ActionConversationChatOwner
                    actionId={action.id}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    store={conversationStore}
                />
                <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
            </Stack>
        )
    }

    return (
        <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
            <ActionAgentInteraction
                action={action}
                assignmentContext={assignmentContext}
                popupEntryId={popupEntryId}
                runtime={runtime}
            />
            <ActionScheduleOwner action={action} context={baseContext} store={scheduleStore} />
            <ActionRunDisabledMessage action={action} settingsStore={settingsStore} />
            {runValidationError ? (
                <Typography color="error.main" role="alert" variant="caption">
                    {runValidationError}
                </Typography>
            ) : null}
        </Stack>
    )
}

import { useEffect, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { cardPopupService, subscribeCardPopups } from '../../../services/card_popup_service'
import { agentAcknowledgementService } from '../../../services/agents/agent_acknowledgement_service'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionConversationChat } from './action_conversation_chat'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationChatOwnerProps {
    actionId: string
    context: ActionContext
    popupEntryId?: string
    store: ActionConversationStore
}

/** Subscribes chat boundary to selected conversation, scoped acknowledgement, and popup stacking. */
export function ActionConversationChatOwner(props: ActionConversationChatOwnerProps) {
    const { actionId, context, popupEntryId, store } = props
    const liveConversation = useActionRunSelector(actionId, context, (run) => run?.conversation ?? null)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const popupEntries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const cardInternalId = context.cardInternalId
    const conversation = liveConversation ?? selectedConversation
    const status = runStatus === 'idle' && conversation?.status === 'waitingForInput' ? 'waitingForInput' : runStatus
    const visible = !!popupEntryId && popupEntries.at(-1)?.id === popupEntryId && !!cardInternalId && !!conversation

    useEffect(() => {
        if (!popupEntryId || !cardInternalId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, cardInternalId, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId,
            cardInternalId,
            actionId,
            conversation,
            false,
        )
    }, [actionId, cardInternalId, conversation, popupEntryId, visible])

    return <ActionConversationChat conversation={conversation} status={status} />
}

